import {t} from './i18n.js?v=stats-20261008';
import {results,percent} from './progress.js';
import {practiceModules} from './practice-modules.js?v=stats-20261008';
let filter='all';
const score=rows=>percent(rows.filter(x=>x.correct).length,rows.length);
export function statsDashboard(){const all=results(),rows=filter==='week'?all.filter(x=>x.at>=Date.now()-7*86400000):all;const correct=rows.filter(x=>x.correct).length,latest=new Map(rows.map(x=>[x.module+'/'+x.question,x])),total=practiceModules.reduce((n,m)=>n+m.quiz.length,0);const half=Math.floor(rows.length/2),before=rows.slice(0,half),after=rows.slice(half);const topics=['rules','staff','formats','terms','math','decisions'].map(theme=>({theme,rows:rows.filter(x=>x.theme===theme)}));const tested=topics.filter(x=>x.rows.length),strong=[...tested].sort((a,b)=>score(b.rows)-score(a.rows)),weak=[...tested].sort((a,b)=>score(a.rows)-score(b.rows));
return `<div class="stats-dashboard"><div class="page-heading"><div><span class="eyebrow">STATS · POKERINNO</span><h1>${t('stats.evolution')}</h1><p>${t('stats.intro')}</p></div></div><div class="stats-filters"><button data-stats-filter="all" aria-pressed="${filter==='all'}">${t('stats.all')}</button><button data-stats-filter="week" aria-pressed="${filter==='week'}">${t('stats.week')}</button></div><div class="stats-metrics">${[[t('stats.correct'),correct],[t('stats.errors'),rows.length-correct],[t('stats.accuracy'),score(rows)+'%'],[t('stats.done'),latest.size+' / '+total]].map(([label,value])=>`<article><span>${label}</span><strong>${value}</strong></article>`).join('')}</div><section class="stats-panel"><h2>${t('stats.comparison')}</h2><p>${t('stats.compareNote')}</p><div class="stats-duel">${[[t('stats.villain'),before],[t('stats.hero'),after]].map(([label,part])=>`<article><h3>${label}</h3><strong>${rows.length>=2?score(part)+'%':'—'}</strong><p>${part.length} ${t('practice.activities')}</p></article>`).join('')}</div><p class="stats-delta">${rows.length>=2?(score(after)-score(before)>0?'+':'')+(score(after)-score(before))+' '+t('stats.points'):t('stats.needData')}</p></section><section class="stats-panel"><h2>${t('stats.themes')}</h2>${topics.map(({theme,rows:items})=>`<details class="stats-topic"><summary><span>${t('practice.'+theme)}</span><strong>${items.length?score(items)+'%':'—'}</strong><span class="stats-bar"><i style="width:${score(items)}%"></i></span></summary><p>${items.filter(x=>x.correct).length} ${t('stats.correct')} · ${items.filter(x=>!x.correct).length} ${t('stats.errors')}</p>${practiceModules.filter(x=>x.theme===theme).map(m=>{const attempts=items.filter(x=>x.module===m.key);return `<a class="stats-module" href="#practice-module/${m.key}"><span>${m.t?.pt||m.title}</span><strong>${attempts.length?score(attempts)+'%':'—'}</strong></a>`}).join('')}</details>`).join('')}</section><section class="stats-panel"><h2>SWOT</h2><div class="stats-swot">${[['strength',strong[0]?.theme],['weakness',weak[0]?.theme],['opportunity',topics.find(x=>!x.rows.length)?.theme],['threat',null]].map(([key,theme])=>`<article><h3>${t('stats.'+key)}</h3><p>${theme?t('practice.'+theme):t(key==='threat'?'stats.threatText':'stats.needData')}</p></article>`).join('')}</div></section><section class="stats-panel"><h2>${t('stats.study')}</h2><p>${t('stats.studyNote')}</p>${(weak.length?weak.slice(0,2):topics.slice(0,2)).map(({theme})=>`<a class="stats-module" href="#practice-module/${practiceModules.find(m=>m.theme===theme).key}">${t('practice.'+theme)} <span>↗</span></a>`).join('')}</section><section class="stats-panel"><h2>${t('stats.history')}</h2>${rows.length?rows.slice(-12).reverse().map(r=>`<div class="stats-history"><span>${t('practice.'+r.theme)}<small>${new Date(r.at).toLocaleString(document.documentElement.lang||'pt-BR')}</small></span><strong>${t(r.correct?'quiz.correct':'quiz.incorrect')}</strong></div>`).join(''):`<p>${t('stats.empty')}</p>`}</section><p class="stats-storage">${t('stats.local')}</p></div>`}
document.addEventListener('click',event=>{const button=event.target.closest('[data-stats-filter]');if(!button)return;filter=button.dataset.statsFilter;document.querySelector('#app').innerHTML=statsDashboard()});
